pub fn isInitializationDAE(mut inShared: &metamodelica::Ref<BackendDAE::Shared>) -> bool {
    let mut res: bool;
    res = (match &**inShared {
        BackendDAE::Shared {
            backendDAEType: BackendDAE::BackendDAEType::INITIALSYSTEM { .. },
            ..
        } => true,
        _ => false,
    });
    res
}

