fn makeIterVariable(mut iter: &metamodelica::Ref<DAE::ReductionIterator>) -> metamodelica::Ref<BackendDAE::Var> {
    let mut backendVar: metamodelica::Ref<BackendDAE::Var>;
    let mut name: ArcStr;
    let mut cr: metamodelica::Ref<DAE::ComponentRef>;
    name = Expression::reductionIterName(iter);
    cr = ComponentReferenceBasics::makeCrefIdent(name, DAE::T_INTEGER_DEFAULT().clone(), metamodelica::nil());
    backendVar = metamodelica::Ref::new(BackendDAE::Var {
        varName: cr,
        varKind: openmodelica_backend_types::BackendDAE::VarKind::VARIABLE,
        varDirection: openmodelica_frontend_types::DAE::VarDirection::BIDIR,
        varParallelism: openmodelica_frontend_types::DAE::VarParallelism::NON_PARALLEL,
        varType: DAE::T_INTEGER_DEFAULT().clone(),
        bindExp: None,
        tplExp: None,
        arryDim: metamodelica::nil(),
        source: DAE::emptyElementSource().clone(),
        values: None,
        tearingSelectOption: None,
        hideResult: None,
        comment: None,
        connectorType: openmodelica_frontend_types::DAE::ConnectorType::interned_NON_CONNECTOR(),
        innerOuter: openmodelica_frontend_types::DAE::VarInnerOuter::NOT_INNER_OUTER,
        unreplaceable: false,
        initNonlinear: false,
        encrypted: false,
    });
    backendVar
}

fn checkEquationSize(
    mut inEq: metamodelica::Ref<BackendDAE::Equation>,
    mut inEqs: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>,
) -> (
    metamodelica::Ref<BackendDAE::Equation>,
    metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>,
) {
    let mut outEq: metamodelica::Ref<BackendDAE::Equation>;
    let mut outEqs: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
    (outEq, outEqs) = 'mc: {
        let __mc_input = (inEq.clone(), inEqs.clone());
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (e @ Deref @ BackendDAE::Equation::EQUATION { exp: e1, scalar: e2, .. }, wrongEqns) => {
                    let mut wrongEqns1: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
                    let mut t1: metamodelica::Ref<DAE::Type>;
                    let mut t2: metamodelica::Ref<DAE::Type>;
                    let mut b: bool;
                    t1 = Expression::r#typeof(e1.clone())?;
                    t2 = Expression::r#typeof(e2.clone())?;
                    b = Expression::equalTypes(&t1, &t2);
                    wrongEqns1 = List::consOnTrue(!(b), e.clone(), wrongEqns.clone());
                    Ok((e.clone(), wrongEqns1.clone()))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (e @ Deref @ BackendDAE::Equation::SOLVED_EQUATION { componentRef: cr, exp: e1, .. }, wrongEqns) => {
                    let mut wrongEqns1: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
                    let mut t1: metamodelica::Ref<DAE::Type>;
                    let mut t2: metamodelica::Ref<DAE::Type>;
                    let mut b: bool;
                    t1 = Expression::r#typeof(e1.clone())?;
                    t2 = ComponentReference::crefLastType(metamodelica::AsArg::as_arg(&cr))?;
                    b = Expression::equalTypes(&t1, &t2);
                    wrongEqns1 = List::consOnTrue(!(b), e.clone(), wrongEqns.clone());
                    Ok((e.clone(), wrongEqns1.clone()))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                _ => {
                    Ok((inEq.clone(), inEqs.clone()))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        panic!("matchcontinue: no arm matched")
    };
    (outEq, outEqs)
}

pub(crate) fn checkAssertCondition(
    mut cond: &metamodelica::Ref<DAE::Exp>,
    mut message: metamodelica::Ref<DAE::Exp>,
    mut level: &metamodelica::Ref<DAE::Exp>,
    mut info: &SourceInfo,
) -> Result<()> {
    if Flags::getConfigBool(Flags::CHECK_MODEL.clone())? {
        return Ok(());
    }
    let () = 'mc: {
        let __mc_input = info.clone();
        if let Ok(__v) = (|| -> Result<_> {
            let _ = __mc_input.clone() else { return Err("nomatch") };
            if !(!(Expression::isConstFalse(cond))) {
                return Err("guard");
            }
            Ok(())
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            let _ = __mc_input.clone() else { return Err("nomatch") };
            if '__try0: {
                ::match_deref::match_deref! { match &((*level)) {
                    Deref @ DAE::Exp::ENUM_LITERAL { index: 2, .. } => (),
                    _ => break '__try0 Err::<_, _>("pattern mismatch"),
                } };
                Ok::<(), &'static str>(())
            }
            .is_ok()
            {
                return Err("failure(): body succeeded");
            }
            Ok(())
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            let _ = __mc_input.clone() else { return Err("nomatch") };
            let mut messageStr: ArcStr;
            let true = (Expression::isConstFalse(cond)) else {
                return Err("pattern mismatch");
            };
            messageStr = ExpressionBasics::printExpStr(message.clone())?;
            Error::addSourceMessage(
                &(Error::ASSERT_CONSTANT_FALSE_ERROR.clone()),
                list![messageStr.clone()],
                info,
            )?;
            Ok(return Err("fail"))
        })() {
            break 'mc __v;
        }
        return Err("matchcontinue: no arm matched");
    };
    Ok(())
}

// =============================================================================
// Util function at Backend using for lowering and other stuff
