fn generateArrayElements(
    mut clones: &metamodelica::List<metamodelica::Ref<DAE::Exp>>,
    mut indices: &metamodelica::List<metamodelica::Ref<DAE::Exp>>,
    mut iteratorExp: &metamodelica::Ref<DAE::Exp>,
) -> Result<metamodelica::List<metamodelica::Ref<DAE::Exp>>> {
    let mut newElements: metamodelica::List<metamodelica::Ref<DAE::Exp>>;
    newElements = (::match_deref::match_deref! { match (clones, indices) {
        (Deref @ metamodelica::ListNode::Nil, Deref @ metamodelica::ListNode::Nil) => {
            metamodelica::nil()
        },
        (Deref @ metamodelica::ListNode::Cons { head: clone, tail: restClones }, Deref @ metamodelica::ListNode::Cons { head: index, tail: restIndices }) => {
            let mut newElement: metamodelica::Ref<DAE::Exp>;
            let mut newElement2: metamodelica::Ref<DAE::Exp>;
            let mut elements: metamodelica::List<metamodelica::Ref<DAE::Exp>>;
            (newElement, _) = Expression::replaceExp(clone.clone(), iteratorExp.clone(), index.clone())?;
            newElement2 = simplifySubscripts(newElement);
            elements = generateArrayElements(restClones, restIndices, iteratorExp)?;
            metamodelica::cons(newElement2, elements)
        },
        _ => return Err("match: no arm matched"),
    } });
    Ok(newElements)
}

