pub(crate) fn markStateEquations(
    mut syst: &metamodelica::Ref<BackendDAE::EqSystem>,
    mut arr: metamodelica::Array<i32>,
    mut ass1: metamodelica::Array<i32>,
) -> Result<metamodelica::Array<i32>> {
    let mut outIntegerArray: metamodelica::Array<i32>;
    let mut statevarindx_lst: metamodelica::List<i32>;
    let mut eqns: metamodelica::List<i32>;
    let mut m: metamodelica::Array<metamodelica::List<i32>>;
    let mut v: BackendDAE::Variables;
    let (__pa0, __pa1) = ::match_deref::match_deref! { match &((*syst)) {
        Deref @ BackendDAE::EqSystem { orderedVars: __pa0, m: Some(__pa1), .. } => (__pa0.clone(), __pa1.clone()),
        _ => return Err("pattern mismatch"),
    } };
    v = metamodelica::Own::own(__pa0);
    m = metamodelica::Own::own(__pa1);
    if Flags::getConfigEnum(Flags::SYM_SOLVER.clone())? > 0 {
        (_, statevarindx_lst) = BackendVariable::getAllVarIndicesFromVariables(
            v,
            (std::sync::Arc::new(
                move |__a0: metamodelica::Ref<BackendDAE::Var>| -> metamodelica::Result<_> {
                    ::std::result::Result::Ok(BackendVariable::isAlgState(&__a0))
                },
            )
                as std::sync::Arc<dyn ::std::ops::Fn(metamodelica::Ref<BackendDAE::Var>) -> Result<bool> + 'static>),
        )?;
    } else {
        (_, statevarindx_lst) = BackendVariable::getAllVarIndicesFromVariables(
            v,
            (std::sync::Arc::new(
                move |__a0: metamodelica::Ref<BackendDAE::Var>| -> metamodelica::Result<_> {
                    ::std::result::Result::Ok(BackendVariable::isStateVar(&__a0))
                },
            )
                as std::sync::Arc<dyn ::std::ops::Fn(metamodelica::Ref<BackendDAE::Var>) -> Result<bool> + 'static>),
        )?;
    }
    eqns = ({
        let mut __acc: metamodelica::List<i32> = metamodelica::nil();
        for mut i in (statevarindx_lst).into_iter().cloned() {
            if !(metamodelica::arrayGet(ass1.clone(), i.clone())? > 0) {
                continue;
            }
            let __x = metamodelica::arrayGet(ass1.clone(), i.clone())?;
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    });
    outIntegerArray = markStateEquationsWork(eqns, m.clone(), ass1.clone(), arr.clone())?;
    Ok(outIntegerArray)
}

pub(crate) fn zeroCrossingVarIndices(
    mut systs: &metamodelica::List<metamodelica::Ref<BackendDAE::EqSystem>>,
    mut zeroCross: &metamodelica::List<BackendDAE::ZeroCrossing>,
) -> Result<metamodelica::Array<metamodelica::Ref<AvlSetInt::Tree>>> {
    let mut trees: metamodelica::Array<metamodelica::Ref<AvlSetInt::Tree>>;
    let mut nsys: i32 = ((systs).len() as i32);
    let mut total: i32 = 0;
    let mut gidx: i32 = 0;
    let mut s: i32 = 0;
    let mut n: i32;
    let mut allVars: BackendDAE::Variables;
    let mut sysOf: metamodelica::Array<i32>;
    let mut locOf: metamodelica::Array<i32>;
    let mut tree: metamodelica::Ref<AvlSetInt::Tree>;
    trees = arrayCreate(intMax(nsys, 1), AvlSetInt::new());
    for mut syst in &**systs {
        total = total + BackendVariable::varsSize(&syst.orderedVars);
    }
    if total == 0 {
        return Ok(trees);
    }
    allVars = BackendVariable::emptyVarsSized(total);
    sysOf = arrayCreate(total, 0);
    locOf = arrayCreate(total, 0);
    for mut syst in &**systs {
        s = s + 1;
        n = BackendVariable::varsSize(&syst.orderedVars);
        for mut i in 1..=n {
            allVars = BackendVariable::addNewVar(BackendVariable::getVarAt(&syst.orderedVars, i)?, allVars)?;
            gidx = gidx + 1;
            metamodelica::arrayUpdate(sysOf.clone(), gidx, s)?;
            metamodelica::arrayUpdate(locOf.clone(), gidx, i)?;
        }
    }
    tree = AvlSetInt::new();
    for mut zc in &**zeroCross {
        tree = BackendEquation::expressionVarsIndexes(
            zc.relation_.clone(),
            tree,
            &({
                let __pe_b2 = allVars.clone();
                move |__pe_a0, __pe_a1| {
                    Ok(BackendEquation::checkEquationsVarsExpTopDown(
                        __pe_a0, __pe_a1, &__pe_b2,
                    ))
                }
            }),
        )?;
    }
    for mut gi in &*AvlSetInt::listKeys(&tree, metamodelica::nil()) {
        s = metamodelica::arrayGet(sysOf.clone(), gi.clone())?;
        metamodelica::arrayUpdate(
            trees.clone(),
            s,
            AvlSetInt::add(
                metamodelica::arrayGet(trees.clone(), s)?,
                metamodelica::arrayGet(locOf.clone(), gi.clone())?,
            )?,
        )?;
    }
    Ok(trees)
}

pub(crate) fn markZeroCrossingEquations(
    mut syst: &metamodelica::Ref<BackendDAE::EqSystem>,
    mut zcVars: &metamodelica::Ref<AvlSetInt::Tree>,
    mut arr: metamodelica::Array<i32>,
    mut ass1: metamodelica::Array<i32>,
) -> Result<metamodelica::Array<i32>> {
    let mut outIntegerArray: metamodelica::Array<i32>;
    let mut eqns: metamodelica::List<i32>;
    let mut m: metamodelica::Array<metamodelica::List<i32>>;
    let __pa0 = ::match_deref::match_deref! { match &((*syst)) {
        Deref @ BackendDAE::EqSystem { m: Some(__pa0), .. } => __pa0.clone(),
        _ => return Err("pattern mismatch"),
    } };
    m = metamodelica::Own::own(__pa0);
    eqns = ({
        let mut __acc: metamodelica::List<i32> = metamodelica::nil();
        for mut i in (AvlSetInt::listKeys(zcVars, metamodelica::nil())).into_iter().cloned() {
            if !(metamodelica::arrayGet(ass1.clone(), i.clone())? > 0) {
                continue;
            }
            let __x = metamodelica::arrayGet(ass1.clone(), i.clone())?;
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    });
    outIntegerArray = markStateEquationsWork(eqns, m.clone(), ass1.clone(), arr.clone())?;
    Ok(outIntegerArray)
}

fn markStateEquationsWork(
    mut inEqns: metamodelica::List<i32>,
    mut m: metamodelica::Array<metamodelica::List<i32>>,
    mut ass1: metamodelica::Array<i32>,
    mut iMark: metamodelica::Array<i32>,
) -> Result<metamodelica::Array<i32>> {
    let __ab_m = m.borrow();
    let mut oMark: metamodelica::Array<i32> = iMark;
    let mut queue: metamodelica::List<i32> = inEqns;
    let mut j: i32;
    let mut eqn: i32;
    let mut len: i32 = metamodelica::arrayLength(ass1.clone());
    let mut positiveAndUnmarked: bool;
    while !((queue).is_empty()) {
        let (__pa0, __pa1) = ::match_deref::match_deref! { match &(queue) {
            Deref @ metamodelica::ListNode::Cons { head: __pa0, tail: __pa1 } => (__pa0.clone(), __pa1.clone()),
            _ => return Err("pattern mismatch"),
        } };
        eqn = metamodelica::Own::own(__pa0);
        queue = metamodelica::Own::own(__pa1);
        if ({
            let __elt = (*metamodelica::index_checked(&oMark.borrow(), eqn)?).clone();
            __elt
        }) == 0
        {
            metamodelica::arrayUpdate(oMark.clone(), eqn, 1)?;
            for mut i in &*(*metamodelica::index_checked(&__ab_m, eqn)?).clone() {
                if i.clone() > 0 && i.clone() <= len {
                    j = metamodelica::Dangerous::arrayGetNoBoundsChecking(ass1.clone(), i.clone());
                    positiveAndUnmarked = if (j > 0) {
                        metamodelica::arrayGet(oMark.clone(), j)? == 0
                    } else {
                        false
                    };
                    if positiveAndUnmarked {
                        queue = metamodelica::cons(j, queue);
                    }
                }
            }
        }
    }
    Ok(oMark)
}

