fn setMarkedEqnsEvalStage(
    mut eqns: metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>>,
    mut markEqns: metamodelica::Array<i32>,
    mut func: &dyn ::std::ops::Fn(BackendDAE::EvaluationStages) -> Result<BackendDAE::EvaluationStages>,
) -> Result<metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>>> {
    pub type setEvalStage = std::sync::Arc<
        dyn ::std::ops::Fn(BackendDAE::EvaluationStages) -> Result<BackendDAE::EvaluationStages> + 'static,
    >;

    let mut eqns: metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>> = eqns;
    let mut eqn: metamodelica::Ref<BackendDAE::Equation>;
    for mut i in 1..=metamodelica::arrayLength(markEqns.clone()) {
        if ({
            let __elt = (*metamodelica::index_checked(&markEqns.borrow(), i)?).clone();
            __elt
        }) > 0
        {
            eqn = BackendEquation::get(eqns.clone(), i)?;
            eqn = BackendEquation::setEquationEvalStage(eqn, func)?;
            eqns = BackendEquation::setAtIndex(eqns, i, eqn)?;
        }
    }
    Ok(eqns)
}

fn collectEqnsIndexByKind(
    mut inEqns: &metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>,
    mut inVars: &metamodelica::List<metamodelica::Ref<BackendDAE::Var>>,
    mut varIdxs: &metamodelica::List<i32>,
    mut eqnIdxs: metamodelica::List<i32>,
    mut traverserArgs: TraverseIndicesTuple,
) -> Result<TraverseIndicesTuple> {
    let mut traverserArgs: TraverseIndicesTuple = traverserArgs;
    let mut indicesDynamic: metamodelica::List<i32>;
    let mut indicesDiscrete: metamodelica::List<i32>;
    let mut indicesAlgebraic: metamodelica::List<i32>;
    (indicesDynamic, indicesDiscrete, indicesAlgebraic) = traverserArgs;
    for mut v in &**inVars {
        if BackendVariable::isVarDiscrete(metamodelica::AsArg::as_arg(&v)) {
            indicesDiscrete = listAppend(eqnIdxs.clone(), indicesDiscrete);
        }
    }
    for mut eq in &**inEqns {
        if BackendEquation::isDynamicEquation(metamodelica::AsArg::as_arg(&eq))? {
            indicesDynamic = listAppend(eqnIdxs.clone(), indicesDynamic);
        }
        if BackendEquation::isAuxEquation(metamodelica::AsArg::as_arg(&eq))? {
            indicesAlgebraic = listAppend(eqnIdxs.clone(), indicesAlgebraic);
        }
    }
    traverserArgs = (indicesDynamic, indicesDiscrete, indicesAlgebraic);
    Ok(traverserArgs)
}

