fn removediscreteAssingmentsElse(
    mut inElse: &metamodelica::Ref<DAE::Else>,
    mut inVars: BackendDAE::Variables,
) -> Result<metamodelica::Ref<DAE::Else>> {
    let mut outElse: metamodelica::Ref<DAE::Else>;
    outElse = (match &**inElse {
        DAE::Else::NOELSE { .. } => openmodelica_frontend_types::DAE::Else::interned_NOELSE(),
        DAE::Else::ELSEIF {
            exp: e,
            statementLst: st,
            else_: el,
        } => {
            let mut vars = inVars;
            let mut st = (*st).clone();
            let mut el = (*el).clone();
            el = removediscreteAssingmentsElse(metamodelica::AsArg::as_arg(&el), vars.clone())?;
            st = removeDiscreteAssignments(metamodelica::AsArg::as_arg(&st), vars)?;
            metamodelica::Ref::new(DAE::Else::ELSEIF {
                exp: e.clone(),
                statementLst: st.clone(),
                else_: el.clone(),
            })
        }
        DAE::Else::ELSE { statementLst: st } => {
            let mut vars = inVars;
            let mut st = (*st).clone();
            st = removeDiscreteAssignments(metamodelica::AsArg::as_arg(&st), vars)?;
            metamodelica::Ref::new(DAE::Else::ELSE {
                statementLst: st.clone(),
            })
        }
    });
    Ok(outElse)
}

