pub(crate) fn adjacencyMatrixDispatch(
    mut inVars: &BackendDAE::Variables,
    mut inEqns: metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>>,
    mut inIndexType: BackendDAE::IndexType,
    mut functionTree: Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
    mut isInitial: bool,
) -> Result<(
    metamodelica::Array<metamodelica::List<i32>>,
    metamodelica::Array<metamodelica::List<i32>>,
)> {
    let mut outAdjacencyArray: metamodelica::Array<metamodelica::List<i32>>;
    let mut outAdjacencyArrayT: metamodelica::Array<metamodelica::List<i32>>;
    let mut num_eqs: i32;
    let mut num_vars: i32;
    let mut eq: metamodelica::Ref<BackendDAE::Equation>;
    let mut row: metamodelica::List<i32>;
    let mut rowLst: metamodelica::List<i32>;
    num_eqs = BackendEquation::getNumberOfEquations(inEqns.clone());
    num_vars = BackendVariable::varsSize(inVars);
    outAdjacencyArray = arrayCreate(num_eqs, metamodelica::nil());
    outAdjacencyArrayT = arrayCreate(num_vars, metamodelica::nil());
    for mut idx in 1..=num_eqs {
        eq = BackendEquation::get(inEqns.clone(), idx)?;
        (rowLst, _) = adjacencyRow(
            &eq,
            inVars,
            inIndexType,
            functionTree.clone(),
            &(metamodelica::nil()),
            isInitial,
        )?;
        row = uniqueRow(rowLst)?;
        metamodelica::arrayUpdate(outAdjacencyArray.clone(), idx, row.clone())?;
        outAdjacencyArrayT = filladjacencyMatrixT(&row, list![idx], outAdjacencyArrayT.clone())?;
    }
    Ok((outAdjacencyArray, outAdjacencyArrayT))
}

