fn adjacencyMatrixDispatchScalar(
    mut inVars: &BackendDAE::Variables,
    mut inEqns: metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>>,
    mut inIndexType: BackendDAE::IndexType,
    mut functionTree: Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
    mut isInitial: bool,
) -> Result<(
    metamodelica::Array<metamodelica::List<i32>>,
    metamodelica::Array<metamodelica::List<i32>>,
    metamodelica::Array<metamodelica::List<i32>>,
    metamodelica::Array<i32>,
)> {
    let mut outAdjacencyArray: metamodelica::Array<metamodelica::List<i32>>;
    let mut outAdjacencyArrayT: metamodelica::Array<metamodelica::List<i32>>;
    let mut omapEqnIncRow: metamodelica::Array<metamodelica::List<i32>>;
    let mut omapIncRowEqn: metamodelica::Array<i32>;
    let mut num_eqs: i32;
    let mut num_vars: i32;
    let mut size: i32;
    let mut num_rows: i32 = 0;
    let mut eq: metamodelica::Ref<BackendDAE::Equation>;
    let mut rowLst: metamodelica::List<i32>;
    let mut row: metamodelica::List<i32>;
    let mut row_indices: metamodelica::List<i32>;
    let mut imap: metamodelica::List<i32> = metamodelica::nil();
    let mut iarr: metamodelica::List<metamodelica::List<i32>> = metamodelica::nil();
    num_eqs = BackendEquation::getNumberOfEquations(inEqns.clone());
    num_vars = BackendVariable::varsSize(inVars);
    outAdjacencyArrayT = arrayCreate(num_vars, metamodelica::nil());
    omapEqnIncRow = arrayCreate(num_eqs, metamodelica::nil());
    for mut idx in 1..=num_eqs {
        eq = BackendEquation::get(inEqns.clone(), idx)?;
        (rowLst, size) = adjacencyRow(
            &eq,
            inVars,
            inIndexType,
            functionTree.clone(),
            &(metamodelica::nil()),
            isInitial,
        )?;
        row = uniqueRow(rowLst)?;
        row_indices = List::intRange2(num_rows + 1, num_rows + size);
        num_rows = num_rows + size;
        metamodelica::arrayUpdate(omapEqnIncRow.clone(), idx, row_indices.clone())?;
        imap = List::consN(size, idx, imap);
        iarr = List::consN(size, row.clone(), iarr);
        outAdjacencyArrayT = filladjacencyMatrixT(&row, row_indices, outAdjacencyArrayT.clone())?;
    }
    outAdjacencyArray = List::listArrayReverse(iarr)?;
    omapIncRowEqn = List::listArrayReverse(imap)?;
    Ok((outAdjacencyArray, outAdjacencyArrayT, omapEqnIncRow, omapIncRowEqn))
}

fn filladjacencyMatrixT(
    mut eqns: &metamodelica::List<i32>,
    mut eqnsindxs: metamodelica::List<i32>,
    mut inAdjacencyArrayT: metamodelica::Array<metamodelica::List<i32>>,
) -> Result<metamodelica::Array<metamodelica::List<i32>>> {
    let mut outAdjacencyArrayT: metamodelica::Array<metamodelica::List<i32>> = inAdjacencyArrayT.clone();
    let mut row: metamodelica::List<i32>;
    let mut ei: metamodelica::List<i32>;
    let mut eqnsindxsNeg: metamodelica::List<i32>;
    eqnsindxsNeg = ({
        let mut __acc: metamodelica::List<i32> = metamodelica::nil();
        for mut e in (eqnsindxs.clone()).into_iter().cloned() {
            let __x = intNeg(e.clone());
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    });
    for mut v in &**eqns {
        let mut v = v.clone();
        if v < 0 {
            v = intAbs(v);
            ei = eqnsindxsNeg.clone();
        } else {
            ei = eqnsindxs.clone();
        }
        row = listAppend(ei, metamodelica::arrayGet(inAdjacencyArrayT.clone(), v)?);
        metamodelica::arrayUpdate(outAdjacencyArrayT.clone(), v, row)?;
    }
    Ok(outAdjacencyArrayT)
}

