fn stripIterSub(
    mut inExp: metamodelica::Ref<DAE::Exp>,
    mut inIter: ArcStr,
) -> (metamodelica::Ref<DAE::Exp>, bool, ArcStr) {
    let mut outExp: metamodelica::Ref<DAE::Exp>;
    let mut cont: bool;
    let mut outIter: ArcStr = inIter.clone();
    (outExp, cont) = (match &*inExp {
        DAE::Exp::CREF { componentRef: cr, ty } => (
            metamodelica::Ref::new(DAE::Exp::CREF {
                componentRef: ComponentReference::crefStripIterSub(metamodelica::AsArg::as_arg(&cr), &inIter),
                ty: ty.clone(),
            }),
            false,
        ),
        _ => (inExp, true),
    });
    (outExp, cont, outIter)
}

fn adjacencyRowLst(
    mut inEquation: &metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>,
    mut inVariables: &BackendDAE::Variables,
    mut inIndexType: BackendDAE::IndexType,
    mut functionTree: Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
    mut inIntegerLst: metamodelica::List<i32>,
    mut isInitial: bool,
) -> Result<(metamodelica::List<i32>, i32)> {
    let mut outIntegerLst: metamodelica::List<i32> = inIntegerLst;
    let mut rowSize: i32 = 0;
    let mut size: i32;
    for mut eq in &**inEquation {
        (outIntegerLst, size) = adjacencyRow(
            metamodelica::AsArg::as_arg(&eq),
            inVariables,
            inIndexType,
            functionTree.clone(),
            &outIntegerLst,
            isInitial,
        )?;
        rowSize = rowSize + size;
    }
    Ok((outIntegerLst, rowSize))
}

