fn adjacencyRowWhen(
    mut inEquation: &metamodelica::Ref<BackendDAE::WhenEquation>,
    mut inVariables: &BackendDAE::Variables,
    mut inIndexType: BackendDAE::IndexType,
    mut functionTree: Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
    mut inRow: &metamodelica::List<i32>,
    mut isInitial: bool,
) -> Result<metamodelica::List<i32>> {
    let mut outRow: metamodelica::List<i32>;
    outRow = (match &**inEquation {
        BackendDAE::WhenEquation {
            condition: cond,
            whenStmtLst,
            elsewhenPart: oelsewe,
        } => {
            let mut elsewe: metamodelica::Ref<BackendDAE::WhenEquation>;
            outRow = adjacencyRowExp(
                cond.clone(),
                inVariables.clone(),
                inRow.clone(),
                functionTree.clone(),
                inIndexType,
                isInitial,
            )?;
            outRow = adjacencyRowWhenOps(
                whenStmtLst,
                inVariables,
                inIndexType,
                functionTree.clone(),
                outRow,
                isInitial,
            )?;
            if (oelsewe).is_some() {
                let __pa0 = ::match_deref::match_deref! { match &(oelsewe.clone()) {
                    Some(__pa0) => __pa0.clone(),
                    _ => return Err("pattern mismatch"),
                } };
                elsewe = metamodelica::Own::own(__pa0);
                outRow = adjacencyRowWhen(&elsewe, inVariables, inIndexType, functionTree, &outRow, isInitial)?;
            }
            outRow
        }
    });
    Ok(outRow)
}

fn adjacencyRowWhenOps<'__b>(
    mut inWhenOps: &'__b metamodelica::List<BackendDAE::WhenOperator>,
    mut inVariables: &'__b BackendDAE::Variables,
    mut inIndexType: BackendDAE::IndexType,
    mut functionTree: Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
    mut inRow: metamodelica::List<i32>,
    mut isInitial: bool,
) -> Result<metamodelica::List<i32>> {
    let mut outRow: metamodelica::List<i32>;
    outRow = (::match_deref::match_deref! { match inWhenOps {
        Deref @ metamodelica::ListNode::Nil => {
            inRow
        },
        Deref @ metamodelica::ListNode::Cons { head: BackendDAE::WhenOperator::ASSIGN { left: Deref @ DAE::Exp::CREF { componentRef: Deref @ DAE::ComponentRef::WILD { .. }, .. }, right: e2, .. }, tail: rest } => {
            outRow = adjacencyRowExp(e2.clone(), inVariables.clone(), inRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowWhenOps(rest, inVariables, inIndexType, functionTree, outRow, isInitial)?;
            outRow
        },
        Deref @ metamodelica::ListNode::Cons { head: BackendDAE::WhenOperator::ASSIGN { left: e1, right: e2, .. }, tail: rest } => {
            outRow = adjacencyRowExp(e1.clone(), inVariables.clone(), inRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowExp(e2.clone(), inVariables.clone(), outRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowWhenOps(rest, inVariables, inIndexType, functionTree, outRow, isInitial)?;
            outRow
        },
        Deref @ metamodelica::ListNode::Cons { head: BackendDAE::WhenOperator::REINIT { stateVar: cr, value: e2, .. }, tail: rest } => {
            let mut e1: metamodelica::Ref<DAE::Exp>;
            e1 = Expression::crefExp(cr.clone())?;
            outRow = adjacencyRowExp(e1, inVariables.clone(), inRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowExp(e2.clone(), inVariables.clone(), outRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowWhenOps(rest, inVariables, inIndexType, functionTree, outRow, isInitial)?;
            outRow
        },
        Deref @ metamodelica::ListNode::Cons { head: BackendDAE::WhenOperator::ASSERT { condition: e1, message: e2, .. }, tail: rest } => {
            outRow = adjacencyRowExp(e1.clone(), inVariables.clone(), inRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowExp(e2.clone(), inVariables.clone(), outRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowWhenOps(rest, inVariables, inIndexType, functionTree, outRow, isInitial)?;
            outRow
        },
        Deref @ metamodelica::ListNode::Cons { head: BackendDAE::WhenOperator::TERMINATE { message: e1, .. }, tail: rest } => {
            outRow = adjacencyRowExp(e1.clone(), inVariables.clone(), inRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowWhenOps(rest, inVariables, inIndexType, functionTree, outRow, isInitial)?;
            outRow
        },
        Deref @ metamodelica::ListNode::Cons { head: BackendDAE::WhenOperator::NORETCALL { exp: e1, .. }, tail: rest } => {
            outRow = adjacencyRowExp(e1.clone(), inVariables.clone(), inRow, functionTree.clone(), inIndexType, isInitial)?;
            outRow = adjacencyRowWhenOps(rest, inVariables, inIndexType, functionTree, outRow, isInitial)?;
            outRow
        },
        _ => return Err("match: no arm matched"),
    } });
    Ok(outRow)
}

fn adjacencyRowAlgorithm(
    mut exp: metamodelica::Ref<DAE::Exp>,
    mut row: metamodelica::List<i32>,
    mut inVariables: BackendDAE::Variables,
    mut functionTree: Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
    mut inIndexType: BackendDAE::IndexType,
    mut isInitial: bool,
) -> Result<metamodelica::List<i32>> {
    let mut row: metamodelica::List<i32> = row;
    row = adjacencyRowExp(exp, inVariables, row, functionTree, inIndexType, isInitial)?;
    Ok(row)
}

