fn adjacencyRowEnhancedEqnLstIfBranches(
    mut iEqns: &metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>,
    mut inVariables: BackendDAE::Variables,
    mut mark: i32,
    mut rowmark: metamodelica::Array<i32>,
    mut globalKnownVars: &BackendDAE::Variables,
    mut trytosolve: bool,
    mut shared: &metamodelica::Ref<BackendDAE::Shared>,
    mut intpl: &(
        metamodelica::List<i32>,
        metamodelica::List<(
            i32,
            BackendDAE::Solvability,
            metamodelica::List<metamodelica::Ref<DAE::Constraint>>,
        )>,
        i32,
    ),
) -> Result<(
    metamodelica::List<i32>,
    metamodelica::List<(
        i32,
        BackendDAE::Solvability,
        metamodelica::List<metamodelica::Ref<DAE::Constraint>>,
    )>,
    i32,
)> {
    let mut outtpl: (
        metamodelica::List<i32>,
        metamodelica::List<(
            i32,
            BackendDAE::Solvability,
            metamodelica::List<metamodelica::Ref<DAE::Constraint>>,
        )>,
        i32,
    );
    let mut row: metamodelica::List<(
        i32,
        BackendDAE::Solvability,
        metamodelica::List<metamodelica::Ref<DAE::Constraint>>,
    )>;
    let mut iRow: metamodelica::List<(
        i32,
        BackendDAE::Solvability,
        metamodelica::List<metamodelica::Ref<DAE::Constraint>>,
    )>;
    let mut lst: metamodelica::List<i32>;
    let mut inLstAllBranch: metamodelica::List<i32>;
    let mut size: i32;
    let mut iSize: i32;
    (inLstAllBranch, iRow, iSize) = intpl.clone();
    for mut eqn in &**iEqns {
        (row, size, _) = adjacencyRowEnhanced(
            inVariables.clone(),
            metamodelica::AsArg::as_arg(&eqn),
            mark,
            rowmark.clone(),
            globalKnownVars,
            trytosolve,
            shared,
        )?;
        lst = List::map(row.clone(), &fnptr!(Util::tuple31, _))?;
        inLstAllBranch = List::intersectionOnTrue(&lst, &inLstAllBranch, &fnptr!(intEq, i32, i32))?;
        iSize = iSize + size;
        iRow = listAppend(row, iRow);
    }
    outtpl = (inLstAllBranch, iRow, iSize);
    Ok(outtpl)
}

