pub(crate) fn isSolvable(mut solvability: BackendDAE::Solvability, mut strict: bool) -> bool {
    let mut solvable: bool;
    solvable = (match solvability {
        BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. } => false,
        BackendDAE::Solvability::SOLVABILITY_UNSOLVABLE { .. } => false,
        BackendDAE::Solvability::SOLVABILITY_CONST { b: mut b } => b.clone(),
        BackendDAE::Solvability::SOLVABILITY_PARAMETER { b: mut b } => b.clone(),
        BackendDAE::Solvability::SOLVABILITY_LINEAR { b: mut b } => b.clone() && !(strict),
        _ => true,
    });
    solvable
}

