            ::match_deref::match_deref! { match &__mc_input {
                (Deref @ metamodelica::ListNode::Cons { head: _, tail: vlst }, Deref @ metamodelica::ListNode::Cons { head: i, tail: ilst }) => {
                    metamodelica::arrayUpdate(rowmark.clone(), i.clone(), -(mark))?;
                    markBranchVars1(metamodelica::AsArg::as_arg(&vlst), metamodelica::AsArg::as_arg(&ilst), mark, rowmark.clone(), bt)?;
                    Ok(())
                }
                _ => return Err("nomatch"),
            }}
