fn getIfExpBranchVarOccurency(
    mut inExp: metamodelica::Ref<DAE::Exp>,
    mut inBt: metamodelica::Ref<BinaryTree::BinTree>,
) -> Result<(
    metamodelica::Ref<DAE::Exp>,
    bool,
    metamodelica::Ref<BinaryTree::BinTree>,
)> {
    let mut outExp: metamodelica::Ref<DAE::Exp>;
    let mut cont: bool;
    let mut bt: metamodelica::Ref<BinaryTree::BinTree>;
    (outExp, cont, bt) = (::match_deref::match_deref! { match &((inExp.clone(), inBt.clone())) {
        (e @ Deref @ DAE::Exp::IFEXP { expThen: e1, expElse: e2, .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            let mut bt_then: metamodelica::Ref<BinaryTree::BinTree>;
            let mut bt_else: metamodelica::Ref<BinaryTree::BinTree>;
            (_, bt_then) = Expression::traverseExpTopDown(e1.clone(), &getIfExpBranchVarOccurency, BinaryTree::emptyBinTree().clone())?;
            (_, bt_else) = Expression::traverseExpTopDown(e2.clone(), &getIfExpBranchVarOccurency, BinaryTree::emptyBinTree().clone())?;
            bt = BinaryTree::binTreeintersection(&bt_then, bt_else, bt.clone())?;
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::LUNARY { .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::LBINARY { .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::RELATION { .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::RANGE { .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::RANGE { .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::ASUB { exp: e1, .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            (_, bt) = Expression::traverseExpTopDown(e1.clone(), &getIfExpBranchVarOccurency, bt.clone())?;
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::CREF { componentRef: cr, .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            bt = BinaryTree::treeAdd(metamodelica::AsArg::as_arg(&bt), cr.clone(), 0)?;
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "der" }, expLst: Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Exp::CREF { componentRef: cr, .. }, tail: Deref @ metamodelica::ListNode::Nil }, .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            bt = BinaryTree::treeAdd(metamodelica::AsArg::as_arg(&bt), cr.clone(), 0)?;
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "der" }, expLst: Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Exp::CREF { componentRef: cr, .. }, tail: Deref @ metamodelica::ListNode::Nil }, .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            bt = BinaryTree::treeAdd(metamodelica::AsArg::as_arg(&bt), cr.clone(), 0)?;
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "pre" }, expLst: Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Exp::CREF { .. }, tail: Deref @ metamodelica::ListNode::Nil }, .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "previous" }, expLst: Deref @ metamodelica::ListNode::Cons { head: Deref @ DAE::Exp::CREF { .. }, tail: Deref @ metamodelica::ListNode::Nil }, .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            (e.clone(), false, bt.clone())
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "delay" }, expLst: Deref @ metamodelica::ListNode::Cons { head: _, tail: Deref @ metamodelica::ListNode::Cons { head: _, tail: Deref @ metamodelica::ListNode::Cons { head: e1, tail: Deref @ metamodelica::ListNode::Cons { head: e2, tail: Deref @ metamodelica::ListNode::Nil } } } }, .. }, __esc_bt) => {
            bt = (*__esc_bt).clone();
            let mut b: bool;
            b = Flags::getConfigBool(Flags::DELAY_BREAK_LOOP.clone())? && ExpressionBasics::expEqual(metamodelica::AsArg::as_arg(&e1), e2.clone())?;
            (e.clone(), !(b), bt.clone())
        },
        (Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "homotopy" }, expLst: Deref @ metamodelica::ListNode::Cons { head: e1, tail: Deref @ metamodelica::ListNode::Cons { head: _, tail: Deref @ metamodelica::ListNode::Nil } }, .. }, _) => {
            getIfExpBranchVarOccurency(e1.clone(), inBt)?
        },
        _ => {
            (inExp, true, inBt)
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok((outExp, cont, bt))
}

