pub(crate) fn solvabilityWights(mut solva: BackendDAE::Solvability) -> Result<i32> {
    let mut i: i32;
    i = (match solva {
        BackendDAE::Solvability::SOLVABILITY_SOLVED { .. } => 1,
        BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. } => 2,
        BackendDAE::Solvability::SOLVABILITY_CONST { .. } => 5,
        BackendDAE::Solvability::SOLVABILITY_PARAMETER { b: false } => 0,
        BackendDAE::Solvability::SOLVABILITY_PARAMETER { b: true } => 50,
        BackendDAE::Solvability::SOLVABILITY_LINEAR { b: false } => 0,
        BackendDAE::Solvability::SOLVABILITY_LINEAR { b: true } => 100,
        BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. } => 500,
        BackendDAE::Solvability::SOLVABILITY_UNSOLVABLE { .. } => 1000,
        _ => return Err("match: no arm matched"),
    });
    Ok(i)
}

pub(crate) fn solvabilityCMP(mut sa: BackendDAE::Solvability, mut sb: BackendDAE::Solvability) -> Result<bool> {
    let mut b: bool;
    b = (match (sa, sb) {
        (BackendDAE::Solvability::SOLVABILITY_SOLVED { .. }, BackendDAE::Solvability::SOLVABILITY_SOLVED { .. }) => {
            false
        }
        (_, BackendDAE::Solvability::SOLVABILITY_SOLVED { .. }) => true,
        (BackendDAE::Solvability::SOLVABILITY_SOLVED { .. }, BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. }) => {
            false
        }
        (
            BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. },
            BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. },
        ) => false,
        (_, BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. }) => true,
        (BackendDAE::Solvability::SOLVABILITY_SOLVED { .. }, BackendDAE::Solvability::SOLVABILITY_CONST { .. }) => {
            false
        }
        (BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. }, BackendDAE::Solvability::SOLVABILITY_CONST { .. }) => {
            false
        }
        (BackendDAE::Solvability::SOLVABILITY_CONST { .. }, BackendDAE::Solvability::SOLVABILITY_CONST { .. }) => false,
        (_, BackendDAE::Solvability::SOLVABILITY_CONST { .. }) => true,
        (BackendDAE::Solvability::SOLVABILITY_SOLVED { .. }, BackendDAE::Solvability::SOLVABILITY_PARAMETER { .. }) => {
            false
        }
        (
            BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. },
            BackendDAE::Solvability::SOLVABILITY_PARAMETER { .. },
        ) => false,
        (BackendDAE::Solvability::SOLVABILITY_CONST { .. }, BackendDAE::Solvability::SOLVABILITY_PARAMETER { .. }) => {
            false
        }
        (
            BackendDAE::Solvability::SOLVABILITY_PARAMETER { .. },
            BackendDAE::Solvability::SOLVABILITY_PARAMETER { .. },
        ) => false,
        (_, BackendDAE::Solvability::SOLVABILITY_PARAMETER { .. }) => true,
        (BackendDAE::Solvability::SOLVABILITY_SOLVED { .. }, BackendDAE::Solvability::SOLVABILITY_LINEAR { .. }) => {
            false
        }
        (BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. }, BackendDAE::Solvability::SOLVABILITY_LINEAR { .. }) => {
            false
        }
        (BackendDAE::Solvability::SOLVABILITY_CONST { .. }, BackendDAE::Solvability::SOLVABILITY_LINEAR { .. }) => {
            false
        }
        (BackendDAE::Solvability::SOLVABILITY_PARAMETER { .. }, BackendDAE::Solvability::SOLVABILITY_LINEAR { .. }) => {
            false
        }
        (BackendDAE::Solvability::SOLVABILITY_LINEAR { .. }, BackendDAE::Solvability::SOLVABILITY_LINEAR { .. }) => {
            false
        }
        (_, BackendDAE::Solvability::SOLVABILITY_LINEAR { .. }) => true,
        (BackendDAE::Solvability::SOLVABILITY_SOLVED { .. }, BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. }) => {
            false
        }
        (
            BackendDAE::Solvability::SOLVABILITY_CONSTONE { .. },
            BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. },
        ) => false,
        (BackendDAE::Solvability::SOLVABILITY_CONST { .. }, BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. }) => {
            false
        }
        (
            BackendDAE::Solvability::SOLVABILITY_PARAMETER { .. },
            BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. },
        ) => false,
        (BackendDAE::Solvability::SOLVABILITY_LINEAR { .. }, BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. }) => {
            false
        }
        (
            BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. },
            BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. },
        ) => false,
        (_, BackendDAE::Solvability::SOLVABILITY_NONLINEAR { .. }) => true,
        (
            BackendDAE::Solvability::SOLVABILITY_UNSOLVABLE { .. },
            BackendDAE::Solvability::SOLVABILITY_UNSOLVABLE { .. },
        ) => false,
        (BackendDAE::Solvability::SOLVABILITY_UNSOLVABLE { .. }, _) => true,
        _ => return Err("match: no arm matched"),
    });
    Ok(b)
}

pub(crate) fn getArrayEquationSub(
    mut Index: i32,
    mut inAD: metamodelica::List<Option<i32>>,
    mut inList: &metamodelica::List<(
        i32,
        metamodelica::List<metamodelica::List<metamodelica::Ref<DAE::Subscript>>>,
    )>,
) -> Result<(
    metamodelica::List<metamodelica::Ref<DAE::Subscript>>,
    metamodelica::List<(
        i32,
        metamodelica::List<metamodelica::List<metamodelica::Ref<DAE::Subscript>>>,
    )>,
)> {
    let mut outSubs: metamodelica::List<metamodelica::Ref<DAE::Subscript>>;
    let mut outList: metamodelica::List<(
        i32,
        metamodelica::List<metamodelica::List<metamodelica::Ref<DAE::Subscript>>>,
    )>;
    (outSubs, outList) = 'mc: {
        let __mc_input = (Index, inAD, &**inList);
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (i, ad, Deref @ metamodelica::ListNode::Nil) => {
                    let mut subs: metamodelica::List<metamodelica::Ref<DAE::Subscript>>;
                    let mut subslst: metamodelica::List<metamodelica::List<metamodelica::Ref<DAE::Subscript>>>;
                    let mut subslst1: metamodelica::List<metamodelica::List<metamodelica::Ref<DAE::Subscript>>>;
                    subslst = Expression::dimensionSizesSubcriptsOpt(metamodelica::AsArg::as_arg(&ad))?;
                    let (__pa0, __pa1) = ::match_deref::match_deref! { match &(Expression::rangesToSubscripts(&subslst)?) {
                        Deref @ metamodelica::ListNode::Cons { head: __pa0, tail: __pa1 } => (__pa0.clone(), __pa1.clone()),
                        _ => return Err("pattern mismatch"),
                    } };
                    subs = metamodelica::Own::own(__pa0);
                    subslst1 = metamodelica::Own::own(__pa1);
                    Ok((subs.clone(), list![(i.clone(), subslst1.clone())]))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (i, _, Deref @ metamodelica::ListNode::Cons { head: (ie, Deref @ metamodelica::ListNode::Cons { head: subs, tail: Deref @ metamodelica::ListNode::Nil }), tail: rest }) => {
                    if !((intEq(i.clone(), ie.clone()))) { return Err("guard") }
                    Ok((subs.clone(), rest.clone()))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (i, _, Deref @ metamodelica::ListNode::Cons { head: (ie, Deref @ metamodelica::ListNode::Cons { head: subs, tail: subslst }), tail: rest }) => {
                    if !((intEq(i.clone(), ie.clone()))) { return Err("guard") }
                    Ok((subs.clone(), metamodelica::cons((ie.clone(), subslst.clone()), rest.clone())))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (i, ad, Deref @ metamodelica::ListNode::Cons { head: entry @ (ie, _), tail: rest }) => {
                    if !((!(intEq(i.clone(), ie.clone())))) { return Err("guard") }
                    let mut subs1: metamodelica::List<metamodelica::Ref<DAE::Subscript>>;
                    let mut entrylst: metamodelica::List<(i32, metamodelica::List<metamodelica::List<metamodelica::Ref<DAE::Subscript>>>)>;
                    (subs1, entrylst) = getArrayEquationSub(i.clone(), ad.clone(), metamodelica::AsArg::as_arg(&rest))?;
                    Ok((subs1.clone(), metamodelica::cons(entry.clone(), entrylst.clone())))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (_, _, _) => {
                    let true = (Flags::isSet(Flags::FAILTRACE.clone())?) else { return Err("pattern mismatch") };
                    Debug::trace(literal!("- BackendDAE.getArrayEquationSub failed\n"))?;
                    Ok(return Err("fail"))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        return Err("matchcontinue: no arm matched");
    };
    Ok((outSubs, outList))
}

