pub(crate) fn getEqnsysRhsExp(
    mut inExp: metamodelica::Ref<DAE::Exp>,
    mut inVariables: BackendDAE::Variables,
    mut funcs: Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
    mut oRepl: Option<BackendVarTransform::VariableReplacements>,
) -> Result<metamodelica::Ref<DAE::Exp>> {
    let mut outExp: metamodelica::Ref<DAE::Exp>;
    outExp = (match oRepl {
        Some(mut repl) => {
            let __pa0 = ::match_deref::match_deref! { match &(Expression::traverseExpTopDown(inExp, &getEqnsysRhsExp1, (repl, inVariables, funcs, true))?) {
                (__pa0, (_, _, _, true)) => __pa0.clone(),
                _ => return Err("pattern mismatch"),
            } };
            outExp = metamodelica::Own::own(__pa0);
            (outExp, _) = ExpressionSimplify::simplify(outExp)?;
            outExp
        }
        _ => {
            let mut repl: BackendVarTransform::VariableReplacements;
            repl = makeZeroReplacements(inVariables.clone())?;
            let __pa0 = ::match_deref::match_deref! { match &(Expression::traverseExpTopDown(inExp, &getEqnsysRhsExp1, (repl, inVariables, funcs, true))?) {
                (__pa0, (_, _, _, true)) => __pa0.clone(),
                _ => return Err("pattern mismatch"),
            } };
            outExp = metamodelica::Own::own(__pa0);
            (outExp, _) = ExpressionSimplify::simplify(outExp)?;
            outExp
        }
    });
    Ok(outExp)
}

fn getEqnsysRhsExp1(
    mut inExp: metamodelica::Ref<DAE::Exp>,
    mut inTpl: (
        BackendVarTransform::VariableReplacements,
        BackendDAE::Variables,
        Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
        bool,
    ),
) -> Result<(
    metamodelica::Ref<DAE::Exp>,
    bool,
    (
        BackendVarTransform::VariableReplacements,
        BackendDAE::Variables,
        Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
        bool,
    ),
)> {
    let mut outExp: metamodelica::Ref<DAE::Exp>;
    let mut cont: bool;
    let mut outTpl: (
        BackendVarTransform::VariableReplacements,
        BackendDAE::Variables,
        Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
        bool,
    );
    (outExp, cont, outTpl) = (::match_deref::match_deref! { match &((inExp, inTpl.clone())) {
        (e @ Deref @ DAE::Exp::CREF { .. }, (repl, _, _, _)) => {
            let mut e1: metamodelica::Ref<DAE::Exp>;
            let mut b1: bool;
            (e1, b1) = BackendVarTransform::replaceExp(metamodelica::AsArg::as_arg(&e), metamodelica::AsArg::as_arg(&repl), None);
            e1 = if (b1) {e1} else {e.clone()};
            (e1, false, inTpl)
        },
        (Deref @ DAE::Exp::IFEXP { expCond: cond, expThen: t, expElse: f }, (repl, vars, funcs, b)) => {
            let mut tpl: (BackendVarTransform::VariableReplacements, BackendDAE::Variables, Option<metamodelica::Ref<AvlTreePathFunction::Tree>>, bool);
            let mut t = (*t).clone();
            let mut f = (*f).clone();
            let mut b = (*b).clone();
            let (_, (_, __pa0)) = Expression::traverseExpTopDown(cond.clone(), &fnptr!(getEqnsysRhsExp2, metamodelica::Ref<DAE::Exp>, (BackendDAE::Variables, bool)), (vars.clone(), b.clone()))?;
            b = metamodelica::Own::own(__pa0);
            (t, tpl) = Expression::traverseExpTopDown(t.clone(), &getEqnsysRhsExp1, (repl.clone(), vars.clone(), funcs.clone(), b.clone()))?;
            (f, tpl) = Expression::traverseExpTopDown(f.clone(), &getEqnsysRhsExp1, tpl)?;
            (metamodelica::Ref::new(DAE::Exp::IFEXP { expCond: cond.clone(), expThen: t.clone(), expElse: f.clone() }), false, tpl)
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "der" }, .. }, _) => {
            (e.clone(), true, inTpl)
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "pre" }, .. }, _) => {
            (e.clone(), false, inTpl)
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "previous" }, .. }, _) => {
            (e.clone(), false, inTpl)
        },
        (e @ Deref @ DAE::Exp::CALL { path: Deref @ Absyn::Path::IDENT { name: Deref @ "semiLinear" }, expLst: Deref @ metamodelica::ListNode::Cons { head: cond, tail: Deref @ metamodelica::ListNode::Cons { head: t, tail: Deref @ metamodelica::ListNode::Cons { head: f, tail: Deref @ metamodelica::ListNode::Nil } } }, .. }, _) => {
            let mut e1: metamodelica::Ref<DAE::Exp>;
            let mut e2: metamodelica::Ref<DAE::Exp>;
            let mut zero: metamodelica::Ref<DAE::Exp>;
            let mut exp: metamodelica::Ref<DAE::Exp>;
            let mut tp: metamodelica::Ref<DAE::Type>;
            let mut tpl: (BackendVarTransform::VariableReplacements, BackendDAE::Variables, Option<metamodelica::Ref<AvlTreePathFunction::Tree>>, bool);
            tp = Expression::r#typeof(e.clone())?;
            (zero, _) = Expression::makeZeroExpression(&(Expression::arrayDimension(&tp)))?;
            e1 = Expression::expMul(cond.clone(), t.clone())?;
            e2 = Expression::expMul(cond.clone(), f.clone())?;
            exp = metamodelica::Ref::new(DAE::Exp::IFEXP { expCond: metamodelica::Ref::new(DAE::Exp::RELATION { exp1: cond.clone(), operator: DAE::Operator::GREATEREQ { ty: tp }, exp2: zero, index: -1, optionExpisASUB: None }), expThen: e1, expElse: e2 });
            (exp, tpl) = Expression::traverseExpTopDown(exp, &getEqnsysRhsExp1, inTpl)?;
            (exp, false, tpl)
        },
        (e @ Deref @ DAE::Exp::CALL { expLst, .. }, (repl, vars, funcs, b)) => {
            let mut e = (*e).clone();
            let mut b = (*b).clone();
            let (_, (_, __pa0)) = Expression::traverseExpListTopDown(expLst.clone(), &fnptr!(getEqnsysRhsExp2, metamodelica::Ref<DAE::Exp>, (BackendDAE::Variables, bool)), (vars.clone(), b.clone()))?;
            b = metamodelica::Own::own(__pa0);
            (e, b) = getEqnsysRhsExp3(b.clone(), e.clone(), (repl.clone(), vars.clone(), funcs.clone(), true));
            (e.clone(), false, (repl.clone(), vars.clone(), funcs.clone(), b.clone()))
        },
        (e, (_, _, _, b)) => {
            (e.clone(), b.clone(), inTpl)
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok((outExp, cont, outTpl))
}

fn getEqnsysRhsExp3(
    mut b: bool,
    mut inExp: metamodelica::Ref<DAE::Exp>,
    mut iTpl: (
        BackendVarTransform::VariableReplacements,
        BackendDAE::Variables,
        Option<metamodelica::Ref<AvlTreePathFunction::Tree>>,
        bool,
    ),
) -> (metamodelica::Ref<DAE::Exp>, bool) {
    let mut oExp: metamodelica::Ref<DAE::Exp>;
    let mut notfound: bool = false;
    (oExp, notfound) = 'mc: {
        let __mc_input = (b, &iTpl);
        if let Ok((__v, __wb0)) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                (false, (_, _, funcs, _)) => {
                    let mut e: metamodelica::Ref<DAE::Exp>;
                    let mut notfound: bool = notfound.clone();
                    let __pa0 = ::match_deref::match_deref! { match &(Inline::forceInlineExp(inExp.clone(), (funcs.clone(), list![openmodelica_frontend_types::DAE::InlineType::NORM_INLINE, openmodelica_frontend_types::DAE::InlineType::DEFAULT_INLINE]), DAE::emptyElementSource().clone(), &Ceval::cevalSimpleWithFunctionTreeReturnExp)?) {
                        (__pa0, _, true) => __pa0.clone(),
                        _ => return Err("pattern mismatch"),
                    } };
                    e = metamodelica::Own::own(__pa0);
                    let (__pa1, (_, _, _, __pa2)) = Expression::traverseExpTopDown(e.clone(), &getEqnsysRhsExp1, iTpl.clone())?;
                    e = metamodelica::Own::own(__pa1);
                    notfound = metamodelica::Own::own(__pa2);
                    Ok(((e.clone(), notfound), notfound.clone()))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            notfound = __wb0;
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                _ => {
                    Ok((inExp.clone(), b))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        panic!("matchcontinue: no arm matched")
    };
    (oExp, notfound)
}

