pub(crate) fn traverseAlgorithmExpsWithUpdate<Type_a: Clone + 'static + metamodelica::gc::MMTrace>(
    mut inAlgorithm: metamodelica::Ref<DAE::Algorithm>,
    mut func: Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, Type_a) -> Result<(metamodelica::Ref<DAE::Exp>, Type_a)>
            + 'static,
    >,
    mut inTypeA: Type_a,
) -> Result<(metamodelica::Ref<DAE::Algorithm>, Type_a)> {
    pub type FuncExpType<Type_a: Clone + 'static> = std::sync::Arc<
        dyn ::std::ops::Fn(metamodelica::Ref<DAE::Exp>, Type_a) -> Result<(metamodelica::Ref<DAE::Exp>, Type_a)>
            + 'static,
    >;

    let mut outAlgorithm: metamodelica::Ref<DAE::Algorithm>;
    let mut outTypeA: Type_a;
    (outAlgorithm, outTypeA) = (match &*inAlgorithm {
        DAE::Algorithm { statementLst: stmts } => {
            let mut stmts1: metamodelica::List<metamodelica::Ref<DAE::Statement>>;
            let mut ext_arg_1: Type_a;
            let mut alg: metamodelica::Ref<DAE::Algorithm>;
            (stmts1, ext_arg_1) = DAEUtil::traverseDAEEquationsStmts(stmts.clone(), func.clone(), inTypeA)?;
            alg = if (metamodelica::ReferenceEq::reference_eq(&(stmts.clone()), &(stmts1))) {
                inAlgorithm
            } else {
                metamodelica::Ref::new(DAE::Algorithm { statementLst: stmts1 })
            };
            (alg, ext_arg_1)
        }
    });
    Ok((outAlgorithm, outTypeA))
}

