fn mapSortEqnsDAE(
    mut inSystem: metamodelica::List<metamodelica::Ref<BackendDAE::EqSystem>>,
    mut inShared: metamodelica::Ref<BackendDAE::Shared>,
) -> Result<metamodelica::List<metamodelica::Ref<BackendDAE::EqSystem>>> {
    let mut outSystem: metamodelica::List<metamodelica::Ref<BackendDAE::EqSystem>>;
    outSystem = ({
        let mut __acc: metamodelica::List<metamodelica::Ref<BackendDAE::EqSystem>> = metamodelica::nil();
        for mut syst in (inSystem).into_iter().cloned() {
            let __x = (::match_deref::match_deref! { match &(syst.clone()) {
                Deref @ BackendDAE::EqSystem { matching: Deref @ BackendDAE::Matching::MATCHING { comps: Deref @ metamodelica::ListNode::Cons { head: _, tail: _ }, .. }, .. } => syst.clone(),
                _ => {
                    Error::checkCancel()?;
                    sortEqnsDAEWork(syst.clone(), inShared.clone())?
                },
                _ => unreachable!("match_deref! exhaustiveness placeholder"),
            } });
            __acc = cons(__x, __acc);
        }
        __acc.reverse()
    });
    Ok(outSystem)
}

fn sortEqnsDAEWork(
    mut inSystem: metamodelica::Ref<BackendDAE::EqSystem>,
    mut inShared: metamodelica::Ref<BackendDAE::Shared>,
) -> Result<metamodelica::Ref<BackendDAE::EqSystem>> {
    let mut outSystem: metamodelica::Ref<BackendDAE::EqSystem>;
    let mut syst: metamodelica::Ref<BackendDAE::EqSystem>;
    let mut mapEqnIncRow: metamodelica::Array<metamodelica::List<i32>>;
    let mut mapIncRowEqn: metamodelica::Array<i32>;
    let mut funcs: metamodelica::Ref<AvlTreePathFunction::Tree>;
    match '__try0: {
        funcs = getFunctions(&inShared);
        (syst, _, _, mapEqnIncRow, mapIncRowEqn) = unwrap_break_err!(getAdjacencyMatrixScalar(inSystem.clone(), openmodelica_backend_types::BackendDAE::IndexType::NORMAL, Some(funcs.clone()), isInitializationDAE(&inShared)), '__try0);
        (outSystem, _) = unwrap_break_err!(BackendDAETransform::strongComponentsScalar(syst.clone(), inShared.clone(), mapEqnIncRow.clone(), mapIncRowEqn.clone()), '__try0);
        if unwrap_break_err!(Flags::isSet(Flags::DUMP_SCC_GRAPHML.clone()), '__try0) {
            unwrap_break_err!(dumpStrongComponents(outSystem.clone(), &inShared), '__try0);
        }
        Ok::<_, &'static str>((
            funcs.clone(),
            mapEqnIncRow.clone(),
            mapIncRowEqn.clone(),
            outSystem.clone(),
            syst.clone(),
        ))
    } {
        Ok((__try0_o0, __try0_o1, __try0_o2, __try0_o3, __try0_o4)) => {
            funcs = __try0_o0;
            mapEqnIncRow = __try0_o1;
            mapIncRowEqn = __try0_o2;
            outSystem = __try0_o3;
            syst = __try0_o4;
        }
        Err(__try0_err) => {
            Error::addInternalError(
                literal!("Transformation module sort components failed"),
                metamodelica::sourceInfo!("BackEnd/BackendDAEUtil.mo"),
            )?;
            return Err(__try0_err);
        }
    }
    Ok(outSystem)
}

fn dumpStrongComponents(
    mut isyst: metamodelica::Ref<BackendDAE::EqSystem>,
    mut ishared: &metamodelica::Ref<BackendDAE::Shared>,
) -> Result<()> {
    let () = (match &**ishared {
        BackendDAE::Shared {
            info: BackendDAE::ExtraInfo { fileNamePrefix, .. },
            ..
        } => {
            let mut fileName: ArcStr;
            let mut seqNo: i32;
            seqNo = System::tmpTickIndex(Global::backendDAE_fileSequence.clone());
            fileName = {
                let mut __mm_s = String::new();
                __mm_s.push_str(&*fileNamePrefix);
                __mm_s.push_str(&*literal!("_"));
                __mm_s.push_str(&*intString(seqNo));
                __mm_s.push_str(&*literal!("_Comps"));
                __mm_s.push_str(&*intString(systemSize(&isyst)?));
                __mm_s.push_str(&*literal!(".graphml"));
                ArcStr::from(__mm_s)
            };
            DumpGraphML::dumpSystem(isyst, ishared, None, fileName, false)?;
            ()
        }
    });
    Ok(())
}

