fn selectIndexReductionMethod<
    Type_a: Clone + 'static + metamodelica::gc::MMTrace,
    Type_b: Clone + 'static + metamodelica::gc::MMTrace,
>(
    mut strIndexReductionMethod: &ArcStr,
    mut inIndexReductionMethods: &metamodelica::List<(Type_a, ArcStr, Type_b, ArcStr)>,
) -> Result<(Type_a, ArcStr, Type_b, ArcStr)> {
    let mut outIndexReductionMethod: (Type_a, ArcStr, Type_b, ArcStr);
    outIndexReductionMethod = 'mc: {
        let __mc_input = &**inIndexReductionMethods;
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                Deref @ metamodelica::ListNode::Cons { head: method @ (_, _, _, name), tail: _ } => {
                    if !((stringEqual(&strIndexReductionMethod, &name))) { return Err("guard") }
                    Ok(method.clone())
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                Deref @ metamodelica::ListNode::Cons { head: _, tail: methods } => {
                    let mut method: (Type_a, ArcStr, Type_b, ArcStr);
                    method = selectIndexReductionMethod(strIndexReductionMethod, metamodelica::AsArg::as_arg(&methods))?;
                    Ok(method.clone())
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                _ => {
                    let mut r#str: ArcStr;
                    r#str = stringAppendList(list![literal!("Selection of Index Reduction Method "), strIndexReductionMethod.clone(), literal!(" failed.")]);
                    Error::addMessage(Error::INTERNAL_ERROR.clone(), list![r#str.clone()])?;
                    Ok(return Err("fail"))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        return Err("matchcontinue: no arm matched");
    };
    Ok(outIndexReductionMethod)
}

