fn selectMatchingAlgorithm<Type_a: Clone + 'static + metamodelica::gc::MMTrace>(
    mut strMatchingAlgorithm: &ArcStr,
    mut inMatchingAlgorithms: &metamodelica::List<(Type_a, ArcStr)>,
) -> Result<(Type_a, ArcStr)> {
    let mut outMatchingAlgorithm: (Type_a, ArcStr);
    outMatchingAlgorithm = 'mc: {
        let __mc_input = &**inMatchingAlgorithms;
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                Deref @ metamodelica::ListNode::Cons { head: method @ (_, name), tail: _ } => {
                    if !((stringEqual(&strMatchingAlgorithm, &name))) { return Err("guard") }
                    Ok(method.clone())
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                Deref @ metamodelica::ListNode::Cons { head: _, tail: methods } => {
                    let mut method: (Type_a, ArcStr);
                    method = selectMatchingAlgorithm(strMatchingAlgorithm, metamodelica::AsArg::as_arg(&methods))?;
                    Ok(method.clone())
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        if let Ok(__v) = (|| -> Result<_> {
            ::match_deref::match_deref! { match &__mc_input {
                _ => {
                    let mut r#str: ArcStr;
                    r#str = stringAppendList(list![literal!("Selection of Matching Algorithm "), strMatchingAlgorithm.clone(), literal!(" failed.")]);
                    Error::addMessage(Error::INTERNAL_ERROR.clone(), list![r#str.clone()])?;
                    Ok(return Err("fail"))
                }
                _ => return Err("nomatch"),
            }}
        })() {
            break 'mc __v;
        }
        return Err("matchcontinue: no arm matched");
    };
    Ok(outMatchingAlgorithm)
}

