pub fn getPreOptModulesString() -> Result<metamodelica::List<ArcStr>> {
    let mut strPreOptModules: metamodelica::List<ArcStr>;
    strPreOptModules = Config::getPreOptModules()?;
    Ok(strPreOptModules)
}

pub(crate) fn isDataReconciliationEnabled() -> Result<bool> {
    let mut enabled: bool;
    let drModules: metamodelica::List<ArcStr> = list![
        literal!("dataReconciliation"),
        literal!("dataReconciliationBoundaryConditions"),
        literal!("dataReconciliationStateEstimation")
    ];
    if (openmodelica_util::Globals::uncertaintyExtraction.with(|__root| __root.borrow().clone())).is_some() {
        enabled = true;
        return Ok(enabled);
    }
    for mut m in &*listAppend(
        Flags::getConfigStringList(Flags::PRE_OPT_MODULES_ADD.clone())?,
        getPreOptModulesString()?,
    ) {
        if listMember(m.clone(), drModules.clone()) {
            enabled = true;
            return Ok(enabled);
        }
    }
    enabled = false;
    Ok(enabled)
}

fn deprecatedDebugFlag(
    mut inFlag: Flags::DebugFlag,
    mut inModuleList: metamodelica::List<ArcStr>,
    mut inModule: ArcStr,
    mut inPhase: &ArcStr,
) -> Result<metamodelica::List<ArcStr>> {
    let mut outModuleList: metamodelica::List<ArcStr> = inModuleList.clone();
    if Flags::isSet(inFlag.clone())? {
        outModuleList = metamodelica::cons(inModule.clone(), inModuleList);
        Error::addCompilerWarning({
            let mut __mm_s = String::new();
            __mm_s.push_str(&*literal!("Deprecated debug flag -d="));
            __mm_s.push_str(&*FlagsUtil::debugFlagName(inFlag));
            __mm_s.push_str(&*literal!(" detected. Use --"));
            __mm_s.push_str(&*inPhase);
            __mm_s.push_str(&*literal!("="));
            __mm_s.push_str(&*inModule);
            __mm_s.push_str(&*literal!(" instead."));
            ArcStr::from(__mm_s)
        })?;
    }
    Ok(outModuleList)
}

fn deprecatedConfigFlag(
    mut inFlag: Flags::ConfigFlag,
    mut inModuleList: metamodelica::List<ArcStr>,
    mut inModule: ArcStr,
    mut inPhase: &ArcStr,
) -> Result<metamodelica::List<ArcStr>> {
    let mut outModuleList: metamodelica::List<ArcStr> = inModuleList.clone();
    if Flags::getConfigBool(inFlag.clone())? {
        outModuleList = metamodelica::cons(inModule.clone(), inModuleList);
        Error::addCompilerWarning({
            let mut __mm_s = String::new();
            __mm_s.push_str(&*literal!("Deprecated flag --"));
            __mm_s.push_str(&*FlagsUtil::configFlagName(inFlag));
            __mm_s.push_str(&*literal!(" detected. Use --"));
            __mm_s.push_str(&*inPhase);
            __mm_s.push_str(&*literal!("="));
            __mm_s.push_str(&*inModule);
            __mm_s.push_str(&*literal!(" instead."));
            ArcStr::from(__mm_s)
        })?;
    }
    Ok(outModuleList)
}

pub(crate) fn getPreOptModules(
    mut inPreOptModules: Option<metamodelica::List<ArcStr>>,
) -> Result<
    metamodelica::List<(
        Arc<
            dyn ::std::ops::Fn(
                    metamodelica::Ref<BackendDAE::BackendDAE>,
                ) -> Result<metamodelica::Ref<BackendDAE::BackendDAE>>
                + 'static,
        >,
        ArcStr,
    )>,
> {
    let mut outPreOptModules: metamodelica::List<(BackendDAEFunc::optimizationModule, ArcStr)>;
    let mut preOptModules: metamodelica::List<ArcStr>;
    let mut enabledModules: metamodelica::List<ArcStr> =
        Flags::getConfigStringList(Flags::PRE_OPT_MODULES_ADD.clone())?;
    let mut disabledModules: metamodelica::List<ArcStr> =
        Flags::getConfigStringList(Flags::PRE_OPT_MODULES_SUB.clone())?;
    preOptModules = getPreOptModulesString()?;
    preOptModules = Util::getOptionOrDefault(inPreOptModules, preOptModules);
    if (openmodelica_util::Globals::isInStream.with(|__root| __root.borrow().clone())).is_some() {
        enabledModules = metamodelica::cons(literal!("simplifyInStream"), enabledModules);
    }
    if Flags::getConfigBool(Flags::DEFAULT_OPT_MODULES_ORDERING.clone())? {
        enabledModules = deprecatedDebugFlag(
            Flags::SORT_EQNS_AND_VARS.clone(),
            enabledModules,
            literal!("sortEqnsVars"),
            &(literal!("preOptModules+")),
        )?;
        if Config::acceptOptimicaGrammar()? || Flags::getConfigBool(Flags::GENERATE_DYN_OPTIMIZATION_PROBLEM.clone())? {
            enabledModules = metamodelica::cons(literal!("inputDerivativesForDynOpt"), enabledModules);
            enabledModules = metamodelica::cons(literal!("createDynamicOptimization"), enabledModules);
        }
        if metamodelica::stringEq(
            &(Flags::getConfigString(Flags::REMOVE_SIMPLE_EQUATIONS.clone())?),
            &(literal!("causal")),
        ) || metamodelica::stringEq(
            &(Flags::getConfigString(Flags::REMOVE_SIMPLE_EQUATIONS.clone())?),
            &(literal!("none")),
        ) {
            disabledModules = metamodelica::cons(literal!("removeSimpleEquations"), disabledModules);
        }
        if !(Flags::isSet(Flags::NF_SCALARIZE.clone())?) {
            disabledModules = metamodelica::cons(literal!("inlineArrayEqn"), disabledModules);
        }
    }
    if !(Flags::getConfigBool(Flags::DEFAULT_OPT_MODULES_ORDERING.clone())?) && !((enabledModules).is_empty()) {
        Error::addCompilerError({
            let mut __mm_s = String::new();
            __mm_s.push_str(&*literal!(
                "It's not possible to combine following flags: --preOptModules+=... and --"
            ));
            __mm_s.push_str(&*FlagsUtil::configFlagName(Flags::DEFAULT_OPT_MODULES_ORDERING.clone()));
            __mm_s.push_str(&*literal!("=false"));
            ArcStr::from(__mm_s)
        })?;
        return Err("fail");
    }
    if !(Flags::getConfigBool(Flags::DEFAULT_OPT_MODULES_ORDERING.clone())?) && !((disabledModules).is_empty()) {
        Error::addCompilerError({
            let mut __mm_s = String::new();
            __mm_s.push_str(&*literal!(
                "It's not possible to combine following flags: --postOptModules-=... and --"
            ));
            __mm_s.push_str(&*FlagsUtil::configFlagName(Flags::DEFAULT_OPT_MODULES_ORDERING.clone()));
            __mm_s.push_str(&*literal!("=false"));
            ArcStr::from(__mm_s)
        })?;
        return Err("fail");
    }
    outPreOptModules = selectOptModules(
        &preOptModules,
        &enabledModules,
        &disabledModules,
        &(allPreOptimizationModules()),
    )?;
    Ok(outPreOptModules)
}

