pub(crate) fn getStrongComponentsVarsAndEquations(
    mut comps: &metamodelica::List<metamodelica::Ref<BackendDAE::StrongComponent>>,
    mut varArr: BackendDAE::Variables,
    mut eqArr: metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>>,
) -> Result<(
    metamodelica::List<metamodelica::Ref<BackendDAE::Var>>,
    metamodelica::List<i32>,
    metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>,
    metamodelica::List<i32>,
)> {
    let mut varsOut: metamodelica::List<metamodelica::Ref<BackendDAE::Var>> = metamodelica::nil();
    let mut varIdxsOut: metamodelica::List<i32> = metamodelica::nil();
    let mut eqsOut: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>> = metamodelica::nil();
    let mut eqIdxsOut: metamodelica::List<i32> = metamodelica::nil();
    let mut comp: metamodelica::Ref<BackendDAE::StrongComponent> =
        <metamodelica::Ref<BackendDAE::StrongComponent> as ::std::default::Default>::default();
    let mut eqs: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
    let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
    let mut vIdxs: metamodelica::List<i32>;
    let mut eIdxs: metamodelica::List<i32>;
    for mut comp in &**comps {
        let mut comp = comp.clone();
        (vars, vIdxs, eqs, eIdxs) = getStrongComponentVarsAndEquations(&comp, varArr.clone(), eqArr.clone())?;
        varsOut = listAppend(vars, varsOut);
        varIdxsOut = listAppend(vIdxs, varIdxsOut);
        eqsOut = listAppend(eqs, eqsOut);
        eqIdxsOut = listAppend(eIdxs, eqIdxsOut);
    }
    varsOut = varsOut.reverse();
    varIdxsOut = varIdxsOut.reverse();
    eqsOut = eqsOut.reverse();
    eqIdxsOut = eqIdxsOut.reverse();
    Ok((varsOut, varIdxsOut, eqsOut, eqIdxsOut))
}

pub(crate) fn getStrongComponentVarsAndEquations(
    mut comp: &metamodelica::Ref<BackendDAE::StrongComponent>,
    mut varArr: BackendDAE::Variables,
    mut eqArr: metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>>,
) -> Result<(
    metamodelica::List<metamodelica::Ref<BackendDAE::Var>>,
    metamodelica::List<i32>,
    metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>,
    metamodelica::List<i32>,
)> {
    let mut varsOut: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
    let mut varIdxs: metamodelica::List<i32>;
    let mut eqsOut: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
    let mut eqIdcxs: metamodelica::List<i32>;
    (varsOut, varIdxs, eqsOut, eqIdcxs) = (match &**comp {
        BackendDAE::StrongComponent::SINGLEEQUATION { eqn: eidx, var: vidx } => {
            let mut eq: metamodelica::Ref<BackendDAE::Equation>;
            let mut var: metamodelica::Ref<BackendDAE::Var>;
            var = BackendVariable::getVarAt(&varArr, vidx.clone())?;
            eq = BackendEquation::get(eqArr, eidx.clone())?;
            (list![var], list![vidx.clone()], list![eq], list![eidx.clone()])
        }
        BackendDAE::StrongComponent::EQUATIONSYSTEM {
            eqns: eidxs,
            vars: vidxs,
            ..
        } => {
            let mut eqs: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
            let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
            vars = List::map1(
                vidxs.clone(),
                &move |__a0: i32, __a1: BackendDAE::Variables| BackendVariable::getVarAtIndexFirst(__a0, &__a1),
                varArr,
            )?;
            eqs = BackendEquation::getList(eidxs.clone(), eqArr)?;
            (vars, vidxs.clone(), eqs, eidxs.clone())
        }
        BackendDAE::StrongComponent::SINGLEARRAY { eqn: eidx, vars: vidxs } => {
            let mut eq: metamodelica::Ref<BackendDAE::Equation>;
            let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
            vars = List::map1(
                vidxs.clone(),
                &move |__a0: i32, __a1: BackendDAE::Variables| BackendVariable::getVarAtIndexFirst(__a0, &__a1),
                varArr,
            )?;
            eq = BackendEquation::get(eqArr, eidx.clone())?;
            (vars, vidxs.clone(), list![eq], list![eidx.clone()])
        }
        BackendDAE::StrongComponent::SINGLEALGORITHM { eqn: eidx, vars: vidxs } => {
            let mut eq: metamodelica::Ref<BackendDAE::Equation>;
            let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
            vars = List::map1(
                vidxs.clone(),
                &move |__a0: i32, __a1: BackendDAE::Variables| BackendVariable::getVarAtIndexFirst(__a0, &__a1),
                varArr,
            )?;
            eq = BackendEquation::get(eqArr, eidx.clone())?;
            (vars, vidxs.clone(), list![eq], list![eidx.clone()])
        }
        BackendDAE::StrongComponent::SINGLECOMPLEXEQUATION { eqn: eidx, vars: vidxs } => {
            let mut eq: metamodelica::Ref<BackendDAE::Equation>;
            let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
            vars = List::map1(
                vidxs.clone(),
                &move |__a0: i32, __a1: BackendDAE::Variables| BackendVariable::getVarAtIndexFirst(__a0, &__a1),
                varArr,
            )?;
            eq = BackendEquation::get(eqArr, eidx.clone())?;
            (vars, vidxs.clone(), list![eq], list![eidx.clone()])
        }
        BackendDAE::StrongComponent::SINGLEWHENEQUATION { eqn: eidx, vars: vidxs } => {
            let mut eq: metamodelica::Ref<BackendDAE::Equation>;
            let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
            vars = List::map1(
                vidxs.clone(),
                &move |__a0: i32, __a1: BackendDAE::Variables| BackendVariable::getVarAtIndexFirst(__a0, &__a1),
                varArr,
            )?;
            eq = BackendEquation::get(eqArr, eidx.clone())?;
            (vars, vidxs.clone(), list![eq], list![eidx.clone()])
        }
        BackendDAE::StrongComponent::SINGLEIFEQUATION { eqn: eidx, vars: vidxs } => {
            let mut eq: metamodelica::Ref<BackendDAE::Equation>;
            let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
            vars = List::map1(
                vidxs.clone(),
                &move |__a0: i32, __a1: BackendDAE::Variables| BackendVariable::getVarAtIndexFirst(__a0, &__a1),
                varArr,
            )?;
            eq = BackendEquation::get(eqArr, eidx.clone())?;
            (vars, vidxs.clone(), list![eq], list![eidx.clone()])
        }
        BackendDAE::StrongComponent::TORNSYSTEM {
            strictTearingSet:
                BackendDAE::TearingSet {
                    residualequations: eidxs,
                    tearingvars: vidxs,
                    innerEquations,
                    ..
                },
            ..
        } => {
            let mut otherEqns: metamodelica::List<i32>;
            let mut otherVars: metamodelica::List<i32>;
            let mut otherVarsLst: metamodelica::List<metamodelica::List<i32>>;
            let mut eqs: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
            let mut vars: metamodelica::List<metamodelica::Ref<BackendDAE::Var>>;
            let mut eidxs = (*eidxs).clone();
            let mut vidxs = (*vidxs).clone();
            (otherEqns, otherVarsLst, _) = List::map_3(
                metamodelica::AsArg::as_arg(&innerEquations),
                &move |__a0: BackendDAE::InnerEquation| -> metamodelica::Result<_> {
                    ::std::result::Result::Ok(getEqnAndVarsFromInnerEquation(&__a0))
                },
            )?;
            otherVars = List::flatten(otherVarsLst)?;
            eidxs = listAppend(otherEqns, eidxs.clone());
            vidxs = listAppend(otherVars, vidxs.clone());
            vars = List::map1(
                vidxs.clone(),
                &move |__a0: i32, __a1: BackendDAE::Variables| BackendVariable::getVarAtIndexFirst(__a0, &__a1),
                varArr,
            )?;
            eqs = BackendEquation::getList(eidxs.clone(), eqArr)?;
            (vars, vidxs.clone(), eqs, eidxs.clone())
        }
    });
    Ok((varsOut, varIdxs, eqsOut, eqIdcxs))
}

pub(crate) fn getStrongComponentEquations(
    mut comps: &metamodelica::List<metamodelica::Ref<BackendDAE::StrongComponent>>,
    mut eqs: metamodelica::Ref<ExpandableArray::ExpandableArray<metamodelica::Ref<BackendDAE::Equation>>>,
    mut vars: BackendDAE::Variables,
) -> Result<metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>> {
    let mut eqsOut: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
    let mut comp: metamodelica::Ref<BackendDAE::StrongComponent> =
        <metamodelica::Ref<BackendDAE::StrongComponent> as ::std::default::Default>::default();
    let mut eqLst: metamodelica::List<metamodelica::Ref<BackendDAE::Equation>>;
    eqsOut = metamodelica::nil();
    for mut comp in &**comps {
        let mut comp = comp.clone();
        (_, _, eqLst, _) = getStrongComponentVarsAndEquations(&comp, vars.clone(), eqs.clone())?;
        eqsOut = listAppend(eqLst, eqsOut);
    }
    Ok(eqsOut)
}

